// Original synthesized score. No sampled or third-party game music.
const THEMES={launch:{notes:[48,52,55,60,64,67,72,76,79,84,88,91,96,0,84,0],bass:[36,40,43,48],speed:.1,type:'square'},home:{notes:[69,0,72,0,67,0,64,0,65,0,69,0,64,0,0,0],bass:[45,41,48,40],speed:.32,type:'triangle'},lab:{notes:[72,0,76,79,0,76,74,0,72,0,67,0,69,72,0,0],bass:[48,45,53,55],speed:.15,type:'square'},ship:{notes:[69,0,0,76,0,0,72,0,0,0,67,0,0,0,0,0],bass:[45,48,41,40],speed:.28,type:'triangle'},emergency:{notes:[72,78,72,78,74,80,74,80,72,78,72,78,71,77,71,77],bass:[36,37,36,35],speed:.12,type:'square'},nobel:{notes:[72,76,79,84,0,79,84,86,88,0,84,79,76,79,84,0],bass:[48,53,55,48],speed:.16,type:'square'},extension:{notes:[67,0,71,74,0,71,69,0,67,0,64,0,66,67,0,0],bass:[43,40,48,43],speed:.25,type:'triangle'},bankrupt:{notes:[57,0,0,56,0,0,53,0,0,52,0,0,45,0,0,0],bass:[33,29,36,33],speed:.4,type:'triangle'}};
export class ChipAudio{
constructor(){this.ctx=null;this.timer=null;this.step=0;this.music=.2;this.sfx=.3;this.scene='home';try{const p=JSON.parse(localStorage.getItem('beeyond-audio'));if(p){this.music=Math.max(0,Math.min(.6,Number(p.music)||0));this.sfx=Math.max(0,Math.min(.8,Number(p.sfx)||0));}}catch{}}
async start(){this.ctx??=new AudioContext();await this.ctx.resume();if(!this.timer){this.next=this.ctx.currentTime+.06;this.timer=setInterval(()=>this.schedule(),70);}}
setScene(scene){let key=['lab','workshop','station'].includes(scene)?'lab':['garden','town','mars'].includes(scene)?'extension':scene;if(!THEMES[key])key='home';if(key!==this.scene){this.scene=key;this.step=0;if(this.ctx)this.next=this.ctx.currentTime+.1;}}
note(midi,time,len,volume,type='square'){if(!this.ctx||volume<=0)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.008);g.gain.exponentialRampToValueAtTime(.0001,time+len);o.connect(g);g.connect(this.ctx.destination);o.start(time);o.stop(time+len+.02);}
schedule(){if(this.ctx.state!=='running')return;const t=THEMES[this.scene]||THEMES.home;while(this.next<this.ctx.currentTime+.15){const i=this.step%16,b=t.bass[Math.floor(i/4)];if(t.notes[i]){this.note(t.notes[i],this.next,t.speed*1.7,this.music*.08,t.type);if(this.scene==='ship')this.note(t.notes[i],this.next+.28,.5,this.music*.025,'triangle');}if(i%4===0)this.note(b,this.next,t.speed*3,this.music*.12,'triangle');if(this.scene==='lab')this.note(b+[12,19,24,19][i%4],this.next,.12,this.music*.025,'square');this.next+=t.speed;this.step++;}}
effect(kind='click'){if(!this.ctx)return;const n={click:[76],equip:[72,79],error:[48,46],advance:[60,67,72],success:[72,76,79,84],knock:[43,43],ring:[88,84,88,84],letter:[79]}[kind]||[76];n.forEach((m,i)=>this.note(m,this.ctx.currentTime+i*.08,.1,this.sfx*.1));}
blip(role=3){if(this.ctx&&this.ctx.state==='running')this.note([72,69,79,76][role],this.ctx.currentTime,.04,this.sfx*.025,'square');}
set(k,v){this[k]=Number(v);try{localStorage.setItem('beeyond-audio',JSON.stringify({music:this.music,sfx:this.sfx}));}catch{}}
pause(){if(this.ctx)this.ctx.suspend();}resume(){if(this.ctx){this.next=this.ctx.currentTime+.06;this.ctx.resume();}}
}
